window.kbPageData["views/entry/k-6968cae8cf21349b"] = {"key":"entry/k-6968cae8cf21349b","state":{"route":"entry/k-6968cae8cf21349b"},"node":{"id":"k-6968cae8cf21349b","mode":"k","title":"乡村振兴战略","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#34"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"引用网址未能与本次实际检索资料逐项对应，需核查原出处。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["rural"],"主类":["事实与事件"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论","经济"],"来源主题":["农业与城乡治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"原题引文：包括乡村产业、人才、文化、生态、组织振兴五个方面。","review":{"definition":"原题引文：包括乡村产业、人才、文化、生态、组织振兴五个方面。","explanation":"第34题A项合述了战略的提出和实施的五个方面，因此在选非题中排除A项。十九大报告列出的是产业兴旺、生态宜居、乡风文明、治理有效、生活富裕五项总要求。习近平在2018年3月8日参加十三届全国人大一次会议山东代表团审议时，集中阐述了五个振兴。","references":[{"source":"web-3d08af396229bf84","location":"2018年3月8日山东代表团审议讲话要点条目","quote":"推动乡村产业振兴、人才振兴、文化振兴、生态振兴、组织振兴"}],"evidence":"包括乡村产业、人才、文化、生态、组织振兴五个方面。","disposition":"独立词条","basis":"据原题与所列资料编释。"},"sources":[{"id":"64e0a00ebe161aac","label":"乡村振兴战略","topic":"农业与城乡治理","category":"非时政","text":"1.乡村振兴战略\n党的十九大报告提出实施乡村振兴战略。实施乡村振兴战略，是以习近平同志为核心的\n党中央着眼党和国家事业全局作出的重大决策，是新时代新征程“三农”工作的总抓手。\n实施乡村振兴战略，坚持农业农村优先发展是总方针，产业兴旺、生态宜居、乡风文明、\n治理有效、生活富裕是总要求，建立健全城乡融合发展体制机制和政策体系是制度保障。\n实施乡村振兴战略，要坚持乡村全面振兴，实现乡村产业振兴、人才振兴、文化振兴、\n生态振兴、组织振兴，推动农业全面升级、农村全面进步、农民全面发展。、","source":{"doc":"6cbfb01fe723bba64b75","first":35,"last":35,"page":35,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#34":{"paper":"政治理论必刷100题","n":34,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",10],"asrc":["国省考政治理论必刷100题.pdf",52],"card":"27e2dd203c7da5889459dadf","links":[{"id":"k-6968cae8cf21349b","role":"直接考查","why":"党的十九大报告提出乡村振兴战略，解析据此确认战略的五个方面。"}]}},"terms":{},"references":{"web-3d08af396229bf84":{"name":"《习近平关于“三农”工作论述摘编》主要篇目介绍","url":"https://www.nppa.gov.cn/xxfb/tt/202206/t20220607_665945.html"}},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"}],"units":{"k-6968cae8cf21349b":[["政治理论必刷100题#34"]]}};
